    private void showLoading(){LinearLayout l=page(t("正在连接矿井大厅…","Connecting to the mine lobby…"));add(l,button(t("返回单机","Back to solo"),this::finish,false));}
    private void connect(){if(!api.signedIn()){login();return;}run(()->{api.enter();return api.call("GET","/api/me",null);},value->{JSONObject u=value.getJSONObject("user");uid=u.getString("id");nickname=u.optString("nickname");room=progress.getString(uid+".room","");String body=progress.getString(uid+".pending","");if(!body.isEmpty())try{pending=new JSONObject(body);}catch(JSONException ignored){}if(savedCamera==null)restoreLocal();lobby();schedule(0);},false);}
    private void run(Job job,Done done,boolean quiet){
        if(!foreground||loading)return;loading=true;int epoch=generation;if(!quiet)message(t("正在处理…","Working…"));
        worker.execute(()->{try{JSONObject result=job.run();handler.post(()->{if(epoch!=generation||!foreground)return;loading=false;try{done.receive(result);}catch(Exception ex){message(t("返回数据无法显示，请重试。","Could not display the response. Please retry."));}schedule(800);});}
            catch(Exception ex){handler.post(()->{if(epoch!=generation||!foreground)return;loading=false;handle(ex);schedule(2000);});}});
    }
    private void handle(Exception ex){
        if(ex instanceof PlatformApi.ApiError){PlatformApi.ApiError error=(PlatformApi.ApiError)ex;
            if("UPDATE_REQUIRED".equals(error.code))api.clear();
            if(!api.signedIn()){uid="";room="";pending=null;queued=false;clearBoard();login();}
            else if("NOT_A_MEMBER".equals(error.code)||"ROOM_NOT_FOUND".equals(error.code)||"ROOM_CLOSED".equals(error.code)){room="";pending=null;saveLocal();lobby();}
            message(OnlineText.error(this,error.code));
        }else message(t("连接暂时中断。保留当前局面，恢复后自动核对；断线宽限60秒。","Connection interrupted. Your board is preserved; reconnecting. Grace period: 60 seconds."));
    }
    private void schedule(long delay){handler.removeCallbacks(poll);if(foreground&&!uid.isEmpty())handler.postDelayed(poll,delay);}
    private void pollNow(){if(!foreground||loading||pollBusy){schedule(500);return;}if(uid.isEmpty())return;pollBusy=true;int epoch=generation;
        final String code=room;final boolean queue=queued;
        worker.execute(()->{try{JSONObject response;
            if(!code.isEmpty())response=api.call("POST","/api/mines/rooms/"+code+"/sync",PlatformApi.object());
            else if(queue)response=api.call("POST","/api/mines/matchmaking/poll",null);
            else response=api.call("GET","/api/mines/rooms",null);
            handler.post(()->{if(epoch!=generation||!foreground)return;pollBusy=false;try{
                if(!code.equals(room)){schedule(0);return;}
                if(response.has("room")){JSONObject r=response.getJSONObject("room");room=r.getString("code");queued=false;roomState=r;saveLocal();JSONObject m=response.optJSONObject("match");if(m!=null)showMatch(m);else showRoom(r);}
                else if(queue){message(t("正在等真人队友：","Waiting for players: ")+response.optInt("waiting",1)+" / "+response.optInt("minimum",2));queued=response.optBoolean("queued");}
                else if(response.optString("current","").length()>0&&!response.isNull("current")){room=response.getString("current");saveLocal();}
                if(pending!=null&&!room.isEmpty()&&match!=null&&!loading){if(!pending.optString("match_id").equals(match.optString("id")))clearPending();else retryPending();}
            }catch(Exception ex){message(t("同步数据异常，正在重试。","Synchronization failed; retrying."));}schedule(800);});
        }catch(Exception ex){handler.post(()->{if(epoch!=generation||!foreground)return;pollBusy=false;handle(ex);schedule(2000);});}});
    }
