    // API 33+ dispatches gestures here; older devices retain the hardware-back path.
    @Override public void onAttachedToWindow(){super.onAttachedToWindow();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);}
    private void back(){if(!room.isEmpty())leave();else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){back();}
    private void saveLocal(){if(progress==null||uid.isEmpty())return;SharedPreferences.Editor e=progress.edit().putString(uid+".room",room).putString(uid+".pending",pending==null?"":pending.toString());if(board!=null){Bundle b=new Bundle();board.save(b);b.putString("online.match",panelMatch);b.putString("online.resultShown",resultShown);Parcel p=Parcel.obtain();p.writeBundle(b);e.putString(uid+".view",android.util.Base64.encodeToString(p.marshall(),android.util.Base64.NO_WRAP));p.recycle();}e.apply();}
    private void restoreLocal(){try{String raw=progress.getString(uid+".view","");if(raw.isEmpty()||raw.length()>131072)return;byte[] data=android.util.Base64.decode(raw,0);Parcel p=Parcel.obtain();p.unmarshall(data,0,data.length);p.setDataPosition(0);savedCamera=p.readBundle(getClassLoader());p.recycle();}catch(Exception ignored){savedCamera=null;}}
    private void clearBoard(){if(board!=null){saveLocal();board.dispose();board=null;}panelMatch="";}
    private LinearLayout page(String heading){root.removeAllViews();ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setPadding(dp(18),dp(20),dp(18),dp(24));scroll.addView(shell);root.addView(scroll);add(shell,text("DEEP SECTOR / ONLINE",11,MineTheme.GOLD));add(shell,text(heading,25,MineTheme.INK));banner=text("",13,MineTheme.CYAN);add(shell,banner);return shell;}
